import React, { useEffect, useState } from "react";
import genres from "./genres.json";
import { useNavigate } from "react-router-dom";

const Books = () => {
  const [inputValue, setInputValue] = useState("");
  const [formattedValue, setFormattedValue] = useState("");
  const [selectedGenre, setSelectedGenre] = useState("");
  const [books, setBooks] = useState([]);
  const [loading, setLoading] = useState(false); // Add loading state
  const navigate = useNavigate();

  useEffect(() => {
    const getBooks = async () => {
      setLoading(true); // Show loader
      try {
        const response = await fetch(
          `https://api.bigbookapi.com/search-books?api-key=${import.meta.env.VITE_BIG_BOOK_API_KEY}`
        );
        if (!response.ok) {
          throw new Error("Network response was not ok");
        }
        const result = await response.json();
        setBooks(result.books);
        console.log(result.books);
      } catch (error) {
        console.error("Error fetching conversion data:", error.message);
      } finally {
        setLoading(false); // Hide loader
      }
    };
    getBooks();
  }, []);

  const searchBooks = async () => {
    setLoading(true); // Show loader
    try {
      const response = await fetch(
        `https://api.bigbookapi.com/search-books?api-key=${import.meta.env.VITE_BIG_BOOK_API_KEY}&query=${formattedValue}`
      );
      if (!response.ok) {
        throw new Error("Network response was not ok");
      }
      const result = await response.json();
      setBooks(result.books);
    } catch (error) {
      console.error("Error fetching conversion data:", error.message);
    } finally {
      setLoading(false); // Hide loader
    }
  };

  const handleChange = (event) => {
    const value = event.target.value;
    setInputValue(value);
    const formatted = value.trim().split(/\s+/).join("+");
    setFormattedValue(formatted);
  };

  const getBooksByGenre = async (query) => {
    setLoading(true); // Show loader
    try {
      const response = await fetch(
        `https://api.bigbookapi.com/search-books?api-key=${import.meta.env.VITE_BIG_BOOK_API_KEY}&query=${query}`
      );
      if (!response.ok) {
        throw new Error("Network response was not ok");
      }
      const result = await response.json();
      setBooks(result.books);
    } catch (error) {
      console.error("Error fetching conversion data:", error.message);
    } finally {
      setLoading(false); // Hide loader
    }
  };

  const handleGenre = (e) => {
    setSelectedGenre(e.target.value);
    getBooksByGenre(e.target.value);
  };

  const handleBookClick = (id) => {
    navigate("/book", { state: { id } });
  };

  return (
    <div className="p-6 max-w-7xl mx-auto">
      <h1 className="text-4xl font-bold mb-6 text-center text-gray-800">
        Books Finder
      </h1>

      <div className="flex flex-col md:flex-row items-center gap-4 mb-6">
        <div className="flex items-center gap-2 w-full md:w-auto">
          <label
            htmlFor="wordInput"
            className="text-sm font-medium text-gray-600"
          >
            Enter text:
          </label>
          <input
            id="wordInput"
            type="text"
            value={inputValue}
            onChange={handleChange}
            placeholder="Type here"
            className="w-full md:w-64 px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring focus:ring-red-500"
          />
        </div>

        <button
          className="px-4 py-2 bg-red-600 text-white font-medium rounded-md shadow-md hover:bg-red-700 transition"
          onClick={searchBooks}
        >
          Search
        </button>

        <div className="flex items-center gap-2 w-full md:w-auto">
          <label
            htmlFor="genreSelect"
            className="text-sm font-medium text-gray-600"
          >
            Choose a genre:
          </label>
          <select
            id="genreSelect"
            onChange={handleGenre}
            value={selectedGenre}
            className="w-full md:w-72 px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring focus:ring-red-500"
          >
            <option value="" disabled>
              Select a genre
            </option>
            {genres.map((genre, index) => (
              <option key={index} value={genre}>
                {genre.replace(/_/g, " ")}
              </option>
            ))}
          </select>
        </div>
      </div>

      {loading ? (
        <div className="flex justify-center items-center py-10">
          <div className="loader border-t-4 border-red-600 rounded-full w-12 h-12 animate-spin"></div>
        </div>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
          {books.map((book, index) => (
            <div
              key={book[0].id}
              className="bg-white shadow-md rounded-lg border border-gray-200 overflow-hidden cursor-pointer hover:shadow-lg transition"
              onClick={() => handleBookClick(book[0].id)}
            >
              <div className="aspect-w-1 aspect-h-1 bg-gray-100">
                <img
                  src={book[0].image}
                  alt={book[0].title}
                  className="object-cover w-full h-full"
                />
              </div>
              <div className="p-4 text-center">
                <h2 className="text-lg font-semibold text-gray-800 truncate">
                  {book[0].title}
                </h2>
                {book[0].subtitle && (
                  <p className="text-sm text-gray-500 mt-1">{book[0].subtitle}</p>
                )}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default Books;

